window.products.push({"id":891490,"name":"Tupperware Shape-O Toy","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/01RmK+J4pJL._AC_.gif","description":"Amazon.com A delight for infants, toddlers, and preschoolers age six months and up, this classic toy rattles when it rolls, develops finger dexterity, and, as a child ages, teaches numbers and counting. Made of rugged, colorful plastic, the 6-1/2-inch sphere contains 10 pieces of different shapes for a toddler to fit into corresponding holes in the sphere. To interest preschoolers, each piece has a number on one side corresponding to the number of dots on the other. When it's not being used, the pieces store inside the sphere, which pulls apart with easy-grip handles. Like Tupperware's renowned storage containers, the toy carries a warranty against chipping, cracking, breaking, and peeling. --Fred Brack","images":["https://m.media-amazon.com/images/I/01RmK+J4pJL._AC_.gif","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Amazon marketplace","source_asin":"B00005S6I9","category_path":"Home & Kitchen"},"sku":"BM-891490","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00005S6I9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00005S6I9","price_pending":true,"merchant_ready":false});
